-- 1875: SFEC Enhanced employer guide. SG only; no automatic social sharing.
-- Official TPGateway EED/2026/1, OurWorkforce enhanced programme page and EWTP factsheet checked 2026-10-30.
-- Keeps the current 90% cap distinct from enhanced funding details still to be announced.
-- Editorial hero rendered and visually inspected at 16:9 and the 32:9 centre crop before upload.
SET @is_sg := IF(@mms_instance = 'SG', 1, 0);
INSERT INTO mmd_blog_post (title, url_key, excerpt, content, author, status, published_at, related_skus, hero_image_url, meta_title, meta_description, meta_keywords, linkedin_urn, linkedin_org_urn, facebook_post_id, created_at, updated_at) SELECT 'SFEC Enhanced: Offset Course Fees Upfront from December 2026', 'sfec-enhanced-upfront-course-fee-offset-december-2026', 'SFEC Enhanced launches on 1 December 2026 with a fresh S$10,000 wallet for eligible companies to offset supported training costs upfront.', '<p>From <strong>1 December 2026</strong>, eligible companies will be able to use <strong>SkillsFuture Enterprise Credit (SFEC) (Enhanced)</strong> to offset eligible out-of-pocket costs upfront. A fresh <strong>S$10,000 credit in an online wallet</strong> will help employers invest in workforce transformation and training without waiting for reimbursement after paying the eligible amount first.</p> <p>For employers planning company-sponsored training, the practical change is the timing: the redesigned SFEC can be used <strong>upon enrolment, before the course starts</strong>. For eligible SWDA-funded training courses that attract employer training subsidies, confirm the course, employer and enrolment eligibility before counting an SFEC offset towards the fee.</p> <p><em>Information checked on 30 October 2026. The enhanced scheme launches on 1 December 2026; it is not yet available at the time of writing.</em></p> <h2>What changes with SFEC Enhanced?</h2> <p>The current SFEC operates on a reimbursement basis. The enhanced scheme moves to a <strong>nett-fee wallet model</strong>, allowing eligible employers to use their credit to reduce the amount they need to pay upfront for supported workforce transformation initiatives and courses.</p> <table><thead><tr><th>Feature</th><th>Current SFEC</th><th>SFEC Enhanced</th></tr></thead><tbody><tr><td>Key date</td><td>Expires on 30 November 2026</td><td>Launches on 1 December 2026</td></tr><tr><td>Credit</td><td>Remaining balance from the current allocation</td><td>Fresh S$10,000 for eligible companies</td></tr><tr><td>How support is provided</td><td>Reimbursement after eligible costs are paid and claims approved</td><td>Online wallet to offset eligible costs upfront</td></tr><tr><td>Training planning</td><td>Eligible course runs must finish by 30 November 2026, subject to approval</td><td>Credit can be used at enrolment before the course start date, subject to the enhanced scheme rules</td></tr></tbody></table> <p>The <a href="https://www.tpgateway.gov.sg/resources/announcements-and-circulars/ssg-information-memorandum-eed-2026-1---launch-of-the-redesigned-skillsfuture-enterprise-credit-(sfec)-and-expiry-of-the-current-skillsfuture-enterprise-credit-(sfec)" target="_blank" rel="noopener">official TPGateway memorandum</a> confirms the launch date, fresh credit and upfront offset at enrolment.</p> <h2>Which companies qualify for the fresh S$10,000?</h2> <p>The official Enterprise Workforce Transformation Package factsheet sets out the following eligibility conditions for the qualifying period <strong>1 January to 31 December 2025</strong>. Employers must:</p> <ul><li>Have employed at least <strong>three Singapore Citizens or Permanent Residents every month</strong> throughout that period. These employees must draw a salary and have CPF contributions.</li><li>Not be in default of their <strong>Skills Development Levy (SDL) contributions</strong> during the qualifying period.</li><li>Not have an <strong>inactive ACRA status</strong>.</li></ul> <p>Check your company against the <a href="https://file.go.gov.sg/wdg-factsheet.pdf" target="_blank" rel="noopener">official EWTP factsheet</a> and the latest scheme guidance. Having received the current SFEC does not, by itself, establish eligibility for the enhanced allocation.</p> <h2>How does the upfront course fee offset work?</h2> <p>Start with the course fee after the applicable employer training subsidy. SFEC Enhanced can then offset the approved portion of eligible out-of-pocket costs, subject to the scheme rules and the credit available in the company wallet. The company pays the remaining amount shown on its invoice.</p> <p><strong>Illustrative example:</strong> suppose a company has S$300 of eligible out-of-pocket training costs after the applicable course subsidy. If S$150 is approved for payment from its SFEC Enhanced wallet, the company would pay S$150 of those costs itself. This illustrates the payment timing only; the S$150 offset is hypothetical and is not an announced funding rate. Any other invoice charges must be checked separately.</p> <p>The S$10,000 is a company credit allocation, rather than a S$10,000 cash payment or an allocation for each employee. It does not mean that every course, every charge or the full course fee will be covered.</p> <h2>Can companies use it for SWDA-funded courses?</h2> <p>Employers planning to enrol staff in SWDA-funded courses that attract training subsidies for employers should confirm whether the specific course and enrolment are supported under SFEC Enhanced. The official enhanced programme page confirms support for workforce transformation programmes and training courses, with further funding details to follow.</p> <p>Before committing a training budget, ask the training provider to confirm the course reference, employer subsidy, eligibility for the enhanced scheme, approved wallet offset and remaining amount payable. A course appearing in a training catalogue does not by itself confirm SFEC Enhanced eligibility.</p> <p>The current SFEC supports <strong>up to 90% of eligible out-of-pocket costs</strong>. That is a rule of the current scheme. Do not assume the same percentage automatically applies to SFEC Enhanced: check the published enhanced support level and redemption conditions when available.</p> <h2>What happens to the current SFEC balance?</h2> <p>The current SFEC expires on <strong>30 November 2026</strong>. To qualify for current SFEC support, the course run must be <strong>completed on or before that date</strong>, subject to approval. Registering before the deadline for a course that finishes later does not meet this condition.</p> <p>Unused current SFEC credit will expire at the transition. Do not assume that an unused balance will be added to the fresh S$10,000 enhanced wallet.</p> <p>For current-scheme enrolments involving Singapore Citizens and Permanent Residents, the TPGateway memorandum describes automatic reimbursement based on enrolment records, approved grants and available balance. Employers enrolling foreign employees, excluding LTVP+ holders, must submit the separate current-scheme SFEC claims by 30 November 2026. The <a href="https://www.tpgateway.gov.sg/resources/announcements-and-circulars/swda-information-memorandum-ewtd-2026-1---decommissioning-of-the-current-skillsfuture-enterprise-credit-(sfec)-system-and-key-deadlines-for-the-decommissioning" target="_blank" rel="noopener">August 2026 transition notice</a> also requires training providers to endorse those submitted manual claims by <strong>30 April 2027</strong>; unendorsed claims will lapse. Employers can view transactions in the current system until its decommissioning on <strong>31 July 2027</strong>. These later processing dates do not extend the 30 November 2026 course completion and employer claim submission deadlines.</p> <h2>Plan your company training before enrolment</h2> <ol><li><strong>Identify the skills your team needs.</strong> Choose training tied to a practical workplace outcome, such as improving project planning or producing better search content.</li><li><strong>Check company eligibility.</strong> Review the 2025 employment and SDL conditions and your ACRA status.</li><li><strong>Verify the course and subsidy.</strong> Obtain the course reference and a breakdown of the employer training subsidy and remaining costs.</li><li><strong>Confirm the SFEC arrangement before the course starts.</strong> Check the wallet balance, approved offset and enrolment requirements under the enhanced scheme.</li><li><strong>Budget for the balance.</strong> Confirm the final invoice, including any charges outside the approved offset.</li></ol> <p>For training ideas, explore <a href="https://www.tertiarycourses.com.sg/wsq-project-management-with-generative-ai-genai.html">WSQ Project Management with Generative AI (GenAI)</a> and <a href="https://www.tertiarycourses.com.sg/wsq-generative-ai-for-search-engine-optimization-seo.html">WSQ Generative AI for Search Engine Optimization (SEO)</a>. These are course planning suggestions; confirm the enhanced scheme eligibility for your company and selected run before enrolling.</p> <p><strong>Planning company-sponsored training from December 2026?</strong> <a href="https://www.tertiarycourses.com.sg/contacts">Contact Tertiary Courses</a> with your company details, preferred courses, staff numbers and training dates to discuss suitable training and the applicable funding arrangements.</p> <h2>Frequently asked questions</h2> <h3>When can companies start using SFEC Enhanced?</h3><p>The announced launch date is 1 December 2026. The redesigned credit can offset eligible costs at enrolment before the course starts, subject to the scheme requirements.</p> <h3>Will every company receive S$10,000?</h3><p>No. The fresh allocation is for companies that meet the enhanced scheme eligibility criteria.</p> <h3>Can I use the enhanced wallet now?</h3><p>As at 30 October 2026, the enhanced scheme has not launched. Plan ahead and confirm the available arrangements before enrolling.</p> <h3>Does the enhanced scheme cover 100% of course fees?</h3><p>The announcement does not establish full coverage of all course fees. The approved offset depends on scheme rules, eligible costs and the available wallet balance.</p> <h3>Where can employers check the latest details?</h3><p>Read the <a href="https://www.ourworkforce.gov.sg/programmes-directory/programme/skillsfuture-enterprise-credit-enhanced" target="_blank" rel="noopener">official SFEC Enhanced programme page</a>, the TPGateway memorandum and the EWTP factsheet linked above. Confirm any later updates before making a funding decision.</p>', 'Tertiary Infotech Academy', 1, '2026-10-30', 'TGS-2024049183,TGS-2020503501', 'https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/auto-20261030-071554-sfec-enhanced-offset-course-fees-upfront-from-december-2026.png', 'SFEC Enhanced: S$10,000 Upfront Course Fee Offset', 'From 1 December 2026, eligible companies get a fresh S$10,000 SFEC wallet to offset training costs upfront. Check eligibility and transition dates.', 'SFEC Enhanced, SkillsFuture Enterprise Credit, upfront course fee offset, employer training subsidy, SWDA funded courses, company training Singapore', 'manual-skip', 'manual-skip', 'manual-skip', '2026-10-30 15:30:00', '2026-10-30 15:30:00' FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM (SELECT post_id FROM mmd_blog_post WHERE url_key = 'sfec-enhanced-upfront-course-fee-offset-december-2026') existing);
INSERT IGNORE INTO mmd_blog_post_tag (post_id, tag_id) SELECT p.post_id, t.tag_id FROM mmd_blog_post p JOIN tag t ON t.name IN ('SFEC', 'SkillsFuture', 'Corporate Training') WHERE @is_sg = 1 AND p.url_key = 'sfec-enhanced-upfront-course-fee-offset-december-2026';
